fn decode_cyclic(s: &Vec<i8>) -> Vec<i8> {
    let len = s.len();
    // P = largest multiple of 3 not exceeding len
    let p = len - (len % 3);
    // Prepare the output vector with the same capacity as the input
    let mut res = Vec::with_capacity(len);

    // Process each full chunk of 3 elements
    for chunk in s[..p].chunks(3) {
        // chunk has exactly 3 elements: [a, b, c]
        // We want to rotate them to [c, a, b]
        res.push(chunk[2]);
        res.push(chunk[0]);
        res.push(chunk[1]);
    }

    // Append the remaining tail (len % 3 elements) unchanged
    res.extend_from_slice(&s[p..]);

    res
}

